mapper.select:
SELECT o.*, s.name as service_name, u.username as user_name, u.phone as phone, CONCAT(a.region, a.detail) as address, a.name as contact_name, a.phone as contact_phone FROM orders o LEFT JOIN service s ON o.service_id = s.id LEFT JOIN users u ON o.user_id = u.id LEFT JOIN address a ON o.address_id = a.id
o.merchant_id = #{merchantId} AND o.status = #{status}
ORDER BY o.create_time DESC

SELECT o.*, m.name as merchant_name, u.username as user_name, a.name as address_name, a.phone as address_phone, a.region as address_region, a.detail as address_detail, CONCAT(a.region, a.detail) as address, u.phone as phone FROM orders o LEFT JOIN merchant m ON o.merchant_id = m.id LEFT JOIN users u ON o.user_id = u.id LEFT JOIN address a ON o.address_id = a.id
o.status = #{status}
ORDER BY o.create_time DESC
